<style scoped>
.roboter {
  width: 100%;
  height: auto;
  overflow: visible;
}

/* Den hvite flaten bak robotene: større og litt mot venstre */
.roboter :deep(.flate) {
  transform-box: fill-box;
  transform-origin: center;
  scale: 1.3;
  translate: -28px -32px;
}

/* Taleluft fra munnen: venstre robot snakker først, så svarer den til høyre */
.roboter :deep(.luft) {
  transform-box: fill-box;
  opacity: 0;
}
.roboter :deep(.luft.venstre) {
  transform-origin: left center;
  animation: ut-hoyre 3.2s ease-out infinite;
}
.roboter :deep(.luft.hoyre) {
  transform-origin: right center;
  animation: ut-venstre 3.2s ease-out 1.6s infinite;
}

@keyframes ut-hoyre {
  0% { opacity: 0; scale: 0.8; translate: -2px 0; }
  10% { opacity: 1; scale: 1.6; translate: 2px 0; }
  30% { opacity: 1; scale: 2; translate: 6px 0; }
  45% { opacity: 0; scale: 2.3; translate: 10px 0; }
  100% { opacity: 0; scale: 2.3; translate: 10px 0; }
}
@keyframes ut-venstre {
  0% { opacity: 0; scale: 0.8; translate: 2px 0; }
  10% { opacity: 1; scale: 1.6; translate: -2px 0; }
  30% { opacity: 1; scale: 2; translate: -6px 0; }
  45% { opacity: 0; scale: 2.3; translate: -10px 0; }
  100% { opacity: 0; scale: 2.3; translate: -10px 0; }
}

@media (prefers-reduced-motion: reduce) {
  .roboter :deep(.luft) {
    animation: none;
    opacity: 1;
  }
}
</style>
